sql-set.sql:
-- 1. User info with manager and profile SELECT U.[Id] AS [UserId], U.[EmpId], U.[EmpType], U.[auth_type], U.[UserName], U.[FirstName], U.[LastName], U.[Email], U.[SecondaryEmail], U.[PhoneNumber], U.[Extension], U.[mobile], U.[oid], U.[preferred_username], U.[display_name], U.[given_name], U.[family_name], U.[Position], U.[BusinessUnit], U.[ManagerId], M.[UserName] AS [ManagerUserName], U.[AccessLevel], U.[IsActive], U.[Designation], U.[Department], U.[Location], U.[Organization], U.[CorrelationId], U.[AuditableRequestId], U.[AuditableRequestName], U.[AuditableSourceEventName], U.[CreatedBy], U.[CreatedDateTime], U.[UpdatedBy], U.[UpdatedDateTime], U.[UpdateReason], U.[OwnerId], U.[IsDeleted], U.[IsApproved], U.[ApproverId], U.[ApprovedDateTime], U.[IsAuthorized], U.[AuthorizedById], U.[AuthorizedDateTime], U.[SysData], U.[TenantId], U.[SubTenantId] FROM [User] AS U LEFT JOIN [User] AS M ON U.[ManagerId] = M.[Id] AND (M.[IsDeleted] IS NULL OR M.[IsDeleted] = 0) LEFT JOIN [UserProfile] AS UP ON UP.[UserId] = U.[Id] WHERE (U.[IsDeleted] IS NULL OR U.[IsDeleted] = 0) AND (U.[Id] = @userId OR U.[oid] = @userId OR U.[UserName] = @userId) ORDER BY U.[display_name] ASC;
-- 2. User Roles SELECT UR.[Id] AS [UserRoleId], R.[Id] AS [Id], R.[RoleName], R.[RoleValue], R.[DisplayName], U.[UserName], U.[Id] AS [UserId] FROM [UserRole] AS UR JOIN [Role] AS R ON (R.[IsDeleted] IS NULL OR R.[IsDeleted] = 0) AND UR.[RoleId] = R.[Id] JOIN [User] AS U ON (U.[IsDeleted] IS NULL OR U.[IsDeleted] = 0) AND UR.[UserId] = U.[Id] WHERE (UR.[IsDeleted] IS NULL OR UR.[IsDeleted] = 0) AND ( UR.[UserId] = @userId OR U.[oid] = @userId OR U.[UserName] = @userId OR @userId IS NULL OR @userId = '0' ) ORDER BY R.[RoleName] ASC;
-- 3. User Permissions Granted SELECT P.[Id] AS [PermissionId], PG.[Id] AS [PermissionGrantedId], P.[PermissionValue], P.[PermissionDisplayName], U.[UserName], U.[Id] AS [UserId], P.[PermissionSetId], AR.[DisplayName] AS [PermissionSetName], P.[ModuleId], A.[DisplayName] AS [ModuleName], P.[ApiName], P.[PermissionType], P.[ActionPermissionEndPoint]
FROM [PermissionGranted] AS PG JOIN [Permission] AS P ON P.[Id] = PG.[PermissionId] AND (P.[IsDeleted] IS NULL OR P.[IsDeleted] = 0) JOIN [User] AS U ON (U.[IsDeleted] IS NULL OR U.[IsDeleted] = 0) AND PG.[UserId] = U.[Id] JOIN [AuthReferenceLookup] AS A ON A.[Id] = P.[ModuleId] JOIN [AuthReferenceLookup] AS AR ON AR.[Id] = P.[PermissionSetId] WHERE (PG.[IsDeleted] IS NULL OR PG.[IsDeleted] = 0) AND ( PG.[UserId] = @userId OR U.[oid] = @userId OR U.[UserName] = @userId OR @userId IS NULL OR @userId = '0' ) ORDER BY P.[PermissionDisplayName] ASC;
-- 4. User Permissions Denied SELECT P.[Id] AS [PermissionId], PD.[Id] AS [PermissionDeniedId], P.[PermissionValue], P.[PermissionDisplayName], U.[UserName], U.[Id] AS [UserId], P.[PermissionSetId], AR.[DisplayName] AS [PermissionSetName], P.[ModuleId], A.[DisplayName] AS [ModuleName], P.[ApiName], P.[PermissionType], P.[ActionPermissionEndPoint] FROM [PermissionDenied] AS PD JOIN [Permission] AS P ON P.[Id] = PD.[PermissionId] AND (P.[IsDeleted] IS NULL OR P.[IsDeleted] = 0) JOIN [User] AS U ON (U.[IsDeleted] IS NULL OR U.[IsDeleted] = 0) AND PD.[UserId] = U.[Id] JOIN [AuthReferenceLookup] AS A ON A.[Id] = P.[ModuleId] JOIN [AuthReferenceLookup] AS AR ON AR.[Id] = P.[PermissionSetId] WHERE (PD.[IsDeleted] IS NULL OR PD.[IsDeleted] = 0) AND ( PD.[UserId] = @userId OR U.[oid] = @userId OR U.[UserName] = @userId OR @userId IS NULL OR @userId = '0' ) ORDER BY P.[PermissionDisplayName] ASC;

-- 1. User info with manager and profile SELECT U.[Id] AS [Id], U.[EmpId], U.[EmpType], U.[UserName], U.[FirstName], U.[LastName], U.[Email], U.[SecondaryEmail], U.[PhoneNumber], U.[Extension], U.[mobile], U.[oid], U.[preferred_username], U.[display_name], U.[given_name], U.[family_name], U.[Position], U.[BusinessUnit], U.[ManagerId], M.[UserName] AS [ManagerUserName], U.[AccessLevel], U.[IsActive], U.[Designation], U.[Department], U.[Location], U.[Organization], U.[CorrelationId], U.[AuditableRequestId], U.[AuditableRequestName], U.[AuditableSourceEventName], U.[CreatedBy], U.[CreatedDateTime], U.[UpdatedBy], U.[UpdatedDateTime], U.[UpdateReason], U.[OwnerId], U.[IsDeleted], U.[IsApproved], U.[ApproverId], U.[ApprovedDateTime], U.[IsAuthorized], U.[AuthorizedById], U.[AuthorizedDateTime], U.[SysData], U.[TenantId], U.[SubTenantId], U.[auth_type] FROM [User] AS U LEFT JOIN [User] AS M ON U.[ManagerId] = M.[Id] AND (M.[IsDeleted] IS NULL OR M.[IsDeleted] = 0) LEFT JOIN [UserProfile] AS UP ON UP.[UserId] = U.[Id] WHERE (U.[IsDeleted] IS NULL OR U.[IsDeleted] = 0) AND ( U.[Id] = @userId OR U.[oid] = @userId OR U.[UserName] = @userId OR @userId IS NULL OR @userId = '0' ) ORDER BY U.[display_name] ASC;
-- 2. User Roles SELECT UR.[Id] AS [UserRoleId], R.[Id] AS [Id], R.[RoleName], R.[RoleValue], R.[DisplayName], U.[UserName], U.[Id] AS [UserId] FROM [UserRole] AS UR JOIN [Role] AS R ON (R.[IsDeleted] IS NULL OR R.[IsDeleted] = 0) AND UR.[RoleId] = R.[Id] JOIN [User] AS U ON (U.[IsDeleted] IS NULL OR U.[IsDeleted] = 0) AND UR.[UserId] = U.[Id] WHERE (UR.[IsDeleted] IS NULL OR UR.[IsDeleted] = 0) AND ( UR.[UserId] = @userId OR U.[oid] = @userId OR U.[UserName] = @userId OR @userId IS NULL OR @userId = '0' ) ORDER BY R.[RoleName] ASC;
-- 3. User Permissions Granted SELECT P.[Id] AS [PermissionId], PG.[Id] AS [PermissionGrantedId], P.[PermissionValue], P.[PermissionDisplayName], U.[UserName], U.[Id] AS [UserId], P.[PermissionSetId], AR.[DisplayName] AS [PermissionSetName], P.[ModuleId], A.[DisplayName] AS [ModuleName], P.[ApiName], P.[PermissionType], P.[IsActive], P.[ActionPermissionEndPoint] FROM [PermissionGranted] AS PG JOIN [Permission] AS P ON P.[Id] = PG.[PermissionId] AND (P.[IsDeleted] IS NULL OR P.[IsDeleted] = 0) JOIN [User] AS U ON (U.[IsDeleted] IS NULL OR U.[IsDeleted] = 0) AND PG.[UserId] = U.[Id] JOIN [AuthReferenceLookup] AS A ON A.[Id] = P.[ModuleId] JOIN [AuthReferenceLookup] AS AR ON AR.[Id] = P.[PermissionSetId] WHERE (PG.[IsDeleted] IS NULL OR PG.[IsDeleted] = 0) AND ( PG.[UserId] = @userId OR U.[oid] = @userId OR U.[UserName] = @userId OR @userId IS NULL OR @userId = '0' ) ORDER BY P.[PermissionDisplayName] ASC;
-- 4. User Permissions Denied SELECT P.[Id] AS [PermissionId], PD.[Id] AS [PermissionDeniedId], P.[PermissionValue], P.[PermissionDisplayName], U.[UserName], U.[Id] AS [UserId], P.[PermissionSetId], AR.[DisplayName] AS [PermissionSetName], P.[ModuleId], A.[DisplayName] AS [ModuleName], P.[ApiName], P.[PermissionType], P.[IsActive], P.[ActionPermissionEndPoint]
FROM [PermissionDenied] AS PD JOIN [Permission] AS P ON P.[Id] = PD.[PermissionId] AND (P.[IsDeleted] IS NULL OR P.[IsDeleted] = 0) JOIN [User] AS U ON (U.[IsDeleted] IS NULL OR U.[IsDeleted] = 0) AND PD.[UserId] = U.[Id] JOIN [AuthReferenceLookup] AS A ON A.[Id] = P.[ModuleId] JOIN [AuthReferenceLookup] AS AR ON AR.[Id] = P.[PermissionSetId] WHERE (PD.[IsDeleted] IS NULL OR PD.[IsDeleted] = 0) AND ( PD.[UserId] = @userId OR U.[oid] = @userId OR U.[UserName] = @userId OR @userId IS NULL OR @userId = '0' ) ORDER BY P.[PermissionDisplayName] ASC;
-- 5. User UI Permissions (from Role assignments only) WITH role_id_list AS ( SELECT STRING_AGG(CAST([RoleId] AS VARCHAR(MAX)), ',') AS [RoleIdList] FROM [UserRole] INNER JOIN [User] AS U ON U.[Id] = [UserRole].[UserId] WHERE [UserId] = @userId OR U.[UserName] = @userId OR @userId IS NULL OR @userId = '0' ), role_id_array AS ( SELECT value AS [RoleId] FROM role_id_list CROSS APPLY STRING_SPLIT([RoleIdList], ',') WHERE [RoleIdList] IS NOT NULL )
SELECT U.[UserId], RP.[UiPermissionId] AS [PermissionId], P.[PermissionValue], P.[PermissionDisplayName], P.[UiPermissionTypeId] AS [PermissionTypeId], A.[DisplayName] AS [PermissionTypeName], P.[PermissionParentId], UP.[PermissionDisplayName] AS [PermissionParentName], P.[ModuleId], AR.[DisplayName] AS [ModuleName] FROM [RoleUiPermission] RP INNER JOIN [UiPermission] AS P ON RP.[UiPermissionId] = P.[Id] AND P.[IsActive] = 1 INNER JOIN [AuthReferenceLookup] AS A ON A.[Id] = P.[UiPermissionTypeId] INNER JOIN [AuthReferenceLookup] AS AR ON AR.[Id] = P.[ModuleId] LEFT JOIN [UiPermission] AS UP ON UP.[Id] = P.[PermissionParentId] INNER JOIN [UserRole] AS U ON U.[RoleId] = RP.[RoleId] WHERE RP.[RoleId] IN (SELECT [RoleId] FROM role_id_array) AND ( U.[UserId] = (SELECT TOP 1 [Id] FROM [User] WHERE [Id] = @userId OR [UserName] = @userId) OR @userId IS NULL OR @userId = '0' ) GROUP BY U.[UserId], RP.[UiPermissionId], P.[PermissionValue], P.[PermissionDisplayName], P.[UiPermissionTypeId], A.[DisplayName], P.[PermissionParentId], UP.[PermissionDisplayName], P.[ModuleId], AR.[DisplayName];
-- 6. User Teams SELECT UT.[TeamId] AS [Id], UT.[MemberId], T.[TeamName], T.[TeamShortName], T.[Description], T.[TeamOwnerId], T.[TeamCaptainId] FROM [TeamMember] AS UT INNER JOIN [Team] AS T ON T.[Id] = UT.[TeamId] INNER JOIN [User] AS U ON U.[Id] = UT.[MemberId] WHERE (T.[IsDeleted] IS NULL OR T.[IsDeleted] = 0) AND (UT.[IsDeleted] IS NULL OR UT.[IsDeleted] = 0) AND (U.[IsDeleted] IS NULL OR U.[IsDeleted] = 0) AND (UT.[MemberId] = (SELECT TOP 1 [Id] FROM [User] WHERE [Id] = @userId OR [UserName] = @userId OR [oid] = @userId) OR @userId IS NULL OR @userId = '0');



INSERT INTO [Permission](
    [PermissionValue],
    [PermissionDisplayName],
    [PermissionSetId],
    [PermissionType],
    [ModuleId],
    [CreatedBy],
    [IsAuthorized],
    [OwnerId],
    [SysData],
    [TenantId],
    [SubTenantId],
    [IsDeleted],
    [IsActive],
    [CreatedDateTime],
	[ActionPermissionEndPoint]
)
VALUES (
    @PermissionValue,
    @PermissionDisplayName,
    @PermissionSetId,
    @PermissionType,
    @ModuleId,
    @CreatedBy,
    @IsAuthorized,
    @OwnerId,
    @SysData,
    @TenantId,
    @SubTenantId,
    0,
    1,
    GETUTCDATE(),
	@ActionPermissionEndPoint
);

SELECT SCOPE_IDENTITY();



-- Delete all permissions for the Role
DELETE FROM [RolePermission]
WHERE [RoleId] = @RoleId;

-- If Permission exists
INSERT INTO [RolePermission](
    [RoleId],
    [CreatedDateTime],
    [CreatedBy],
    [UpdatedDateTime],
    [UpdatedBy],
    [IsDeleted],
    [IsActive],
    [IsAuthorized],
    [OwnerId],
    [SysData],
    [TenantId],
    [SubTenantId],
    [PermissionId]
)
SELECT
    @RoleId,
    GETUTCDATE(),
    @CreatedBy,
    GETUTCDATE(),
    @CreatedBy,
    0,
    1,
    @IsAuthorized,
    @OwnerId,
    @SysData,
    @TenantId,
    @SubTenantId,
    value AS [PermissionId]
FROM STRING_SPLIT(@PermissionIds, ',')
WHERE @PermissionIds IS NOT NULL
  AND @PermissionIds <> '';



INSERT INTO [RoleUiPermission](
    [RoleId],
    [UiPermissionId],
    [CreatedBy],
    [CreatedDateTime]
)
VALUES (
    @RoleId,
    @UiPermissionId,
    @CreatedBy,
    GETUTCDATE()
);



INSERT INTO [UiPermission](
    [PermissionValue],
    [PermissionDisplayName],
    [UiPermissionTypeId],
    [PermissionParentId],
    [ModuleId],
    [CreatedBy],
    [IsAuthorized],
    [OwnerId],
    [SysData],
    [TenantId],
    [SubTenantId],
    [IsDeleted],
    [IsActive],
    [CreatedDateTime]
)
VALUES (
    @PermissionValue,
    @PermissionDisplayName,
    @PermissionTypeId,
    @PermissionParentId,
    @ModuleId,
    @CreatedBy,
    @IsAuthorized,
    @OwnerId,
    @SysData,
    @TenantId,
    @SubTenantId,
    0,
    0,
    GETUTCDATE()
);

SELECT SCOPE_IDENTITY();



INSERT INTO [UserRole](
    [UserId],
    [CreatedDateTime],
    [CreatedBy],
    [UpdatedDateTime],
    [UpdatedBy],
    [IsDeleted],
    [IsActive],
    [IsAuthorized],
    [OwnerId],
    [SysData],
    [TenantId],
    [SubTenantId],
    [RoleId]
)
SELECT DISTINCT
    @UserId,
    GETUTCDATE(),
    @CreatedBy,
    GETUTCDATE(),
    @CreatedBy,
    0,
    1,
    @IsAuthorized,
    @OwnerId,
    @SysData,
    @TenantId,
    @SubTenantId,
    @RoleId
WHERE NOT EXISTS (
    SELECT 1
    FROM [UserRole]
    WHERE [UserId] = @UserId
      AND [RoleId] = @RoleId
);

DELETE FROM [UserRole] WHERE [UserId] = @UserId;
INSERT INTO [UserRole]( [UserId], [CreatedDateTime], [CreatedBy], [UpdatedDateTime], [UpdatedBy], [IsDeleted], [IsActive], [IsAuthorized], [OwnerId], [SysData], [TenantId], [SubTenantId], [RoleId] ) SELECT DISTINCT @UserId, GETUTCDATE(), @CreatedBy, GETUTCDATE(), @CreatedBy, 0, 1, @IsAuthorized, @OwnerId, @SysData, @TenantId, @SubTenantId, T.[RoleId] FROM ( SELECT value AS [RoleId] FROM STRING_SPLIT(@RoleIds, ',') WHERE @RoleIds IS NOT NULL AND @RoleIds <> ''
UNION ALL
SELECT [Id] FROM [Role] WHERE [RoleName] = 'User'
) AS T;



DELETE FROM [UserRole]
WHERE [UserId] = @UserId
  AND [RoleId] = @RoleId;

-- NOTE: This query expects @Id1, @Id2, @Id3, @Id4 -- (for protected users) and @PermissionIds -- (comma-separated string) to be resolved in C#.
DELETE FROM [PermissionDenied] WHERE [UserId] = @UserId;
INSERT INTO [PermissionDenied]( [UserId], [CreatedDateTime], [CreatedBy], [UpdatedDateTime], [UpdatedBy], [IsDeleted], [IsActive], [IsAuthorized], [OwnerId], [SysData], [TenantId], [SubTenantId], [PermissionId] ) SELECT DISTINCT @UserId, GETUTCDATE(), @CreatedBy, GETUTCDATE(), @CreatedBy, 0, 1, @IsAuthorized, @OwnerId, @SysData, @TenantId, @SubTenantId, value AS [PermissionId] FROM STRING_SPLIT(@PermissionIds, ',') WHERE @PermissionIds IS NOT NULL AND @PermissionIds <> '';



DELETE FROM [PermissionGranted]
WHERE [UserId] = @UserId;

INSERT INTO [PermissionGranted](
    [UserId],
    [CreatedDateTime],
    [CreatedBy],
    [UpdatedDateTime],
    [UpdatedBy],
    [IsDeleted],
    [IsActive],
    [IsAuthorized],
    [OwnerId],
    [SysData],
    [TenantId],
    [SubTenantId],
    [PermissionId]
)
SELECT DISTINCT
    @UserId,
    GETUTCDATE(),
    @CreatedBy,
    GETUTCDATE(),
    @CreatedBy,
    0,
    1,
    @IsAuthorized,
    @OwnerId,
    @SysData,
    @TenantId,
    @SubTenantId,
    value AS [PermissionId]
FROM STRING_SPLIT(@PermissionIds, ',')
WHERE @PermissionIds IS NOT NULL
  AND @PermissionIds <> '';



INSERT INTO [User] (
    [Id],
    [UserName],
    [auth_type],
    [EmpId],
    [EmpType],
    [mobile],
    [Email],
    [Position],
    [BusinessUnit],
    [oid],
    [given_name],
    [family_name],
    [preferred_username],
    [FirstName],
    [LastName],
    [SecondaryEmail],
    [PhoneNumber],
    [Extension],
    [display_name],
    [ManagerId],
    [Designation],
    [Department],
    [Location],
    [Organization],
    [CreatedDateTime],
    [UpdatedDateTime],
    [IsDeleted],
    [IsActive],
    [IsAuthorized],
    [OwnerId],
    [CreatedBy],
    [UpdatedBy],
    [SysData],
    [TenantId],
    [SubTenantId],
    [AccessLevel]
)
VALUES (
    @Id,
    @UserName,
    @auth_type,
    @EmpId,
    @EmpType,
    @mobile,
    @Email,
    @Position,
    @BusinessUnit,
    @OID,
    @given_name,
    @family_name,
    @preferred_username,
    @FirstName,
    @LastName,
    @SecondaryEmail,
    @PhoneNumber,
    @Extension,
    @display_name,
    @ManagerId,
    @Designation,
    @Department,
    @Location,
    @Organization,
    GETUTCDATE(),
    GETUTCDATE(),
    0,
    1,
    @IsAuthorized,
    @OwnerId,
    @CreatedBy,
    @CreatedBy,
    @SysData,
    @TenantId,
    @SubTenantId,
    @AccessLevel
);

SELECT @Id AS [Id];

INSERT INTO [UserRole] (
    [UserId],
    [RoleId]
)
SELECT
    @Id,
    [Id]
FROM [Role]
WHERE [RoleName] = 'User';

INSERT INTO [UserPasswordHash] (
    [UserId],
    [PasswordHash],
    [UpdatedBy],
    [UpdatedDateTime]
)
VALUES (
    @Id,
    @PasswordHash,
    @CreatedBy,
    GETUTCDATE()
);

-- NOTE: This query contains two UPDATE statements. -- For Dapper, both can be executed in a single command. -- Use transaction handling in C# if atomic operation is required.
UPDATE [User] SET [PhoneNumber] = @PhoneNumber, [Extension] = @Extension, [Email] = @Email, [AccessLevel] = @AccessLevel, [UpdatedBy] = @UpdatedBy, [UpdatedDateTime] = @UpdatedDateTime WHERE [Id] = @Id;
UPDATE [UserRole] SET [RoleId] = @UserRoleId, [UpdatedBy] = @UpdatedBy, [UpdatedDateTime] = @UpdatedDateTime WHERE [UserId] = @Id;



INSERT INTO [UserProfile] (
    [UserId],
    [DateOfJoining],
    [PrimarySkills],
    [SecondarySkills],
    [TertiarySkills],
    [OtherSkills]
)
VALUES (
    @UserId,
    @DateOfJoining,
    @PrimarySkills,
    @SecondarySkills,
    @TertiarySkills,
    @OtherSkills
);


INSERT INTO [UserActivity] (
    [UserId],
    [LastLoginDateTime],
    [LastLogoutDateTime],
    [LastActivityDateTime],
    [LastActivityModule],
    [LastActionType],
    [LastActivityDetail],
    [CreatedBy],
    [CreatedDateTime]
)
OUTPUT INSERTED.[Id]
VALUES (
    @UserId,
    @LastLoginDateTime,
    @LastLogoutDateTime,
    @LastActivityDateTime,
    @LastActivityModule,
    @LastActionType,
    @LastActivityDetail,
    @CreatedBy,
    @CreatedDateTime
)


INSERT INTO [Team](
    [TeamName], [TeamShortName], [Description], [TeamOwnerId], [TeamCaptainId],
    [CreatedBy], [CreatedDateTime], [IsDeleted], [IsActive]
)
OUTPUT INSERTED.[Id]
VALUES(
    @TeamName, @TeamShortName, @Description, @TeamOwnerId, @TeamCaptainId,
    @CreatedBy, GETUTCDATE(), 0, 1
);


INSERT INTO [TeamMember]([MemberId], [TeamId], [CreatedBy], [CreatedDateTime], [IsDeleted])
SELECT
    CAST(value AS UNIQUEIDENTIFIER) AS [MemberId],
    @TeamId AS [TeamId],
    @CreatedBy,
    GETUTCDATE(),
    0
FROM STRING_SPLIT(@MemberIds, ',')
WHERE @MemberIds IS NOT NULL AND @MemberIds <> '';
